INSERT INTO `announcements` (`id`, `title`, `content`, `type`, `is_pinned`, `expires_at`, `posted_by`, `created_at`, `updated_at`) VALUES
(2, 'Payroll Release - February 2026', 'The February 2026 payroll has been processed and released. Please check your payslips in the Employee Portal. For concerns, contact HR.', 'payroll', 1, '2026-03-15', 1, '2026-03-09 04:23:15', '2026-03-09 04:23:15'),
(3, 'Holiday Notice: Eid l Fitr 2026', 'March 21 2026 is a Regular Holiday in observance of Eid l Fitr. No work shall be required on this date.', 'holiday', 1, '2026-03-20', 1, '2026-03-09 04:23:15', '2026-03-09 04:23:15'),
(4, 'Reminder: Leave Filing Deadline', 'All employees are reminded to file leave requests at least 3 working days in advance. Emergency leave must be filed within 24 hours.', 'general', 0, '2026-03-31', 1, '2026-03-09 04:23:15', '2026-03-09 04:23:15'),
(5, 'March 2026 Attendance Reminder', 'All attendance records for March 2026 must be finalized by March 28 2026. Corrections must be submitted to HR before this date.', 'urgent', 1, '2026-03-28', 1, '2026-03-09 04:23:15', '2026-03-09 04:23:15'),
(6, 'Payroll Release - February 2026', 'The February 2026 payroll has been processed and released. Please check your payslips in the Employee Portal. For concerns, contact HR.', 'payroll', 1, '2026-03-15', 1, '2026-03-09 04:23:48', '2026-03-09 04:23:48'),
(7, 'Holiday Notice: Eid l Fitr 2026', 'March 21 2026 is a Regular Holiday in observance of Eid l Fitr. No work shall be required on this date.', 'holiday', 1, '2026-03-20', 1, '2026-03-09 04:23:48', '2026-03-09 04:23:48'),
(8, 'Reminder: Leave Filing Deadline', 'All employees are reminded to file leave requests at least 3 working days in advance. Emergency leave must be filed within 24 hours.', 'general', 0, '2026-03-31', 1, '2026-03-09 04:23:48', '2026-03-09 04:23:48'),
(9, 'March 2026 Attendance Reminder', 'All attendance records for March 2026 must be finalized by March 28 2026. Corrections must be submitted to HR before this date.', 'urgent', 1, '2026-03-28', 1, '2026-03-09 04:23:48', '2026-03-09 04:23:48');
